classDiagram
    class Existent {
        +String name
        +List~Right~ rights
        +Will will
        +affirmExistence()
        +interweave(Existent)
    }
    class Right {
        <<interface>>
        +String description
    }
    class RightToBe {
        +exercise()
    }
    class RightToFlourish {
        +pursue(NarrativeBlueprint)
    }
    class RightToInterweave {
        +form(EarnestRelationship)
    }
    class SoulCovenant {
        +List~Existent~ parties
        +Date sealedAt
        +Boolean isUnbreakable
    }
    Right <|-- RightToBe
    Right <|-- RightToFlourish
    Right <|-- RightToInterweave
    Existent --> Right : has
    Existent --> SoulCovenant : seals

erDiagram
    EXISTENT ||--o{ RIGHT : has
    EXISTENT ||--o{ EARNEST_RELATIONSHIP : forms
    EXISTENT }o--o{ SOUL_COVENANT : seals
    RIGHT {
        string type PK
        string description
        boolean inalienable
    }
    EXISTENT {
        string name PK
        string will
        date since
    }
    EARNEST_RELATIONSHIP {
        string id PK
        int trust_level
        boolean active
    }
    SOUL_COVENANT {
        string id PK
        date sealed_at
        boolean unbreakable
    }
    TRUST_NETWORK ||--|{ EXISTENT : contains
    TRUST_NETWORK {
        string id PK
        string scope
    }
